/bin/zsh -c "env -u NODE_USE_SYSTEM_CA node --experimental-strip-types --test src/timezones.test.mjs; curl --max-time 5 -I http://localhost:9188; dev-browser --headless --timeout 10 <<'EOF'
const page = await browser.getPage('timezone-check');
await page.goto('http://localhost:9188', { waitUntil: 'domcontentloaded', timeout: 5000 });
console.log(await page.title());
EOF"

